// Free months of TapCard Promote for the first restaurants. Codes are generated by the stores (Apple offer
// codes, Google Play promo codes), imported here, and each restaurant gets its own one of each in its email.
import sql from "@/lib/db";

let ready: Promise<unknown> | null = null;
function ensureSchema(): Promise<unknown> {
  if (!ready) {
    ready = sql`
      CREATE TABLE IF NOT EXISTS tapcard_promo_codes (
        code TEXT PRIMARY KEY,
        platform TEXT NOT NULL,
        assigned_contact_id BIGINT,
        assigned_at TIMESTAMPTZ,
        created_at TIMESTAMPTZ NOT NULL DEFAULT now()
      )
    `
      .then(() => sql`CREATE INDEX IF NOT EXISTS tapcard_promo_codes_free ON tapcard_promo_codes (platform) WHERE assigned_contact_id IS NULL`)
      .catch((err) => {
        ready = null;
        throw err;
      });
  }
  return ready;
}

export type PromoPlatform = "ios" | "android";
export const APPLE_APP_ID = "6816003159";

export function redeemUrl(platform: PromoPlatform, code: string): string {
  return platform === "ios"
    ? `https://apps.apple.com/redeem?ctx=offercodes&id=${APPLE_APP_ID}&code=${encodeURIComponent(code)}`
    : `https://play.google.com/redeem?code=${encodeURIComponent(code)}`;
}

/// One code per line (or a CSV: the first column that looks like a code is used).
export async function importPromoCodes(platform: PromoPlatform, text: string): Promise<{ added: number; skipped: number }> {
  await ensureSchema();
  const codes = new Set<string>();
  for (const line of text.split(/\r?\n/)) {
    const cell = line.split(/[,\t;]/).map((c) => c.trim().replace(/^"|"$/g, "")).find((c) => /^[A-Za-z0-9]{6,32}$/.test(c));
    if (cell) codes.add(cell);
  }
  let added = 0;
  for (const code of codes) {
    const r = (await sql`
      INSERT INTO tapcard_promo_codes (code, platform) VALUES (${code}, ${platform}) ON CONFLICT (code) DO NOTHING RETURNING code
    `) as unknown[];
    added += r.length;
  }
  return { added, skipped: codes.size - added };
}

export async function promoCodeStats(): Promise<Record<PromoPlatform, { free: number; assigned: number }>> {
  await ensureSchema();
  const rows = (await sql`
    SELECT platform, COUNT(*) FILTER (WHERE assigned_contact_id IS NULL)::int AS free, COUNT(*) FILTER (WHERE assigned_contact_id IS NOT NULL)::int AS assigned
    FROM tapcard_promo_codes GROUP BY platform
  `) as { platform: PromoPlatform; free: number; assigned: number }[];
  const out = { ios: { free: 0, assigned: 0 }, android: { free: 0, assigned: 0 } };
  for (const r of rows) if (r.platform in out) out[r.platform] = { free: r.free, assigned: r.assigned };
  return out;
}

/// This restaurant's own code for each platform that has one: the same codes again if it was sent before,
/// otherwise the next free one. A test send passes no contact and shows an example, taking nothing.
export async function codesForContact(contactId: number): Promise<{ ios?: string; android?: string }> {
  await ensureSchema();
  const out: { ios?: string; android?: string } = {};
  for (const platform of ["ios", "android"] as const) {
    const mine = (await sql`SELECT code FROM tapcard_promo_codes WHERE assigned_contact_id = ${contactId} AND platform = ${platform} LIMIT 1`) as { code: string }[];
    if (mine[0]) { out[platform] = mine[0].code; continue; }
    const taken = (await sql`
      UPDATE tapcard_promo_codes SET assigned_contact_id = ${contactId}, assigned_at = now()
      WHERE code = (SELECT code FROM tapcard_promo_codes WHERE platform = ${platform} AND assigned_contact_id IS NULL ORDER BY created_at, code LIMIT 1 FOR UPDATE SKIP LOCKED)
      RETURNING code
    `) as { code: string }[];
    if (taken[0]) out[platform] = taken[0].code;
  }
  return out;
}
